public static String convertDatesToWeekdays(String date) {
    if (date == null) return null;
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) return "Invalid input format";
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.format.TextStyle ts = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;
        String monthName = localDate.getMonth().getDisplayName(ts, locale);
        String dayName = localDate.getDayOfWeek().getDisplayName(ts, locale);
        return String.format("%s %d, %d is a %s", monthName, day, year, dayName);
    } catch (Exception e) {
        return "Invalid date";
    }
}

